class Solution {
public:
    int rotatedDigits(int n) {
        int count = 0;
        for (int x = 1; x <= n; x++) {
            int temp = x;
            bool valid = true, diff = false;
            while (temp > 0) {
                int d = temp % 10;
                if (d == 3 || d == 4 || d == 7) { valid = false; break; }
                if (d == 2 || d == 5 || d == 6 || d == 9) diff = true;
                temp /= 10;
            }
            if (valid && diff) count++;
        }
        return count;
    }
};

