var rotatedDigits = function(n) {
    let count = 0;
    for (let x = 1; x <= n; x++) {
        let temp = x;
        let valid = true, diff = false;
        while (temp > 0) {
            const d = temp % 10;
            if (d === 3 || d === 4 || d === 7) { valid = false; break; }
            if (d === 2 || d === 5 || d === 6 || d === 9) diff = true;
            temp = Math.floor(temp / 10);
        }
        if (valid && diff) count++;
    }
    return count;
};
